import{_ as i,l as r,o as e,c as o,v as t,p as s,x as n,d as m,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"Guéant-Lehalle-Fernandez-Tapia","description":"","frontmatter":{"title":"Guéant-Lehalle-Fernandez-Tapia","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/glft-market-making.md","filePath":"quant/glft-market-making.md","lastUpdated":1789023840000}'),h={name:"quant/glft-market-making.md"};function B(E,a,A,c,T,g){const l=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="gueant-lehalle-fernandez-tapia" tabindex="-1">Guéant-Lehalle-Fernandez-Tapia <a class="header-anchor" href="#gueant-lehalle-fernandez-tapia" aria-label="Permalink to &quot;Guéant-Lehalle-Fernandez-Tapia&quot;">​</a></h1><div class="epigraph"><p>把终端库存惩罚写进指数效用之后，做市的最优挂单距离有不显式依赖剩余时间的近似；库存偏度来自该项惩罚，价差来自强度与风险厌恶。</p><footer>—— Guéant, Lehalle and Fernandez-Tapia, Dealing with the Inventory Risk: A Solution to the Market Making Problem under Inventory Constraints, Mathematics and Financial Economics, 2013</footer></div><p><a href="/quant/avellaneda-stoikov">Avellaneda–Stoikov</a> 在有限地平 \\(T\\) 上把无差异价格写成 \\(s-q\\gamma\\sigma^2(T-t)\\)，最优价差含一项随剩余时间放大的库存风险。全天连续做市时，\\(T\\) 是人为的收盘钟，参数随 \\(T-t\\) 漂移，午盘与尾盘的报价公式看起来像两套策略。Guéant、Lehalle 与 Fernandez-Tapia（2013）把问题改写成：指数效用、指数到达强度、对终端库存的二次（或更一般）惩罚，并给出小库存下的闭式近似。结果是一组围绕公允价、随库存平移的最优距离，宽度主要由 \\(\\gamma,\\sigma,\\kappa\\) 与惩罚强度决定，而不必把「距收盘还有多久」当作状态的第一坐标。本篇写 GLFT 相对 AS 改了哪一条目标、近似解长什么样，以及库存硬约束如何进入。它仍是存货模块，不含毒性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>做市商选择买、卖相对中间价的距离 \\(\\delta^b,\\delta^a\\)，成交为强度 \\(\\lambda(\\delta)=A e^{-\\kappa\\delta}\\) 的泊松过程，中间价扩散系数 \\(\\sigma\\)，绝对风险厌恶 \\(\\gamma\\)。AS 的终端条件是在 \\(T\\) 按中间价变现并承受扩散累积的库存方差，因此 \\(T-t\\) 进入一阶条件。实务上交易日结束还有拍卖、隔夜缺口与库存限额，真正被执行的往往是<strong>限额</strong>而不是某个光滑的 \\(T\\)。GLFT 要回答：若目标改为「全天都在做市，但终端库存离开零要付罚」，以及库存不得越出 \\([-Q,Q]\\)，报价如何写成 \\((s,q)\\) 的函数，能否得到可计算的近似，而不是每次解一遍带跳 HJB。</p><p>无库存风险时，竞争把距离推到补偿被捡走期权的水平。有惩罚时，多头必须更积极地卖、更保守地买，与 Ho–Stoll / AS 同一偏度逻辑。差别是惩罚可以是终端一次性的 \\(\\ell(q_T)\\)，也可以在连续时间里用运行成本近似；硬约束 \\(q\\in[-Q,Q]\\) 则在边界上把一侧强度关掉——触及上限后不再买，这是限额而不是更大的 \\(\\gamma\\)。</p><h3 id="终端惩罚替代剩余时间" tabindex="-1">终端惩罚替代剩余时间 <a class="header-anchor" href="#终端惩罚替代剩余时间" aria-label="Permalink to &quot;终端惩罚替代剩余时间&quot;">​</a></h3><p>取指数效用 \\(U=-\\exp(-\\gamma x)\\)，价值函数可分离现金。对库存的终端罚若取二次型或与 AS 扩散项同构的形式，稳态（或长地平）下无差异价格的平移不再乘 \\((T-t)\\)，而乘一个由惩罚系数、\\(\\sigma\\) 与 \\(\\gamma\\) 决定的常数。价差里仍有 \\(\\frac{1}{\\gamma}\\ln(1+\\gamma/\\kappa)\\) 这类强度项。于是同一套 \\((\\gamma,\\kappa,A,\\text{penalty})\\) 可以在开盘与午盘共用，尾盘若真的要强平，再把惩罚系数随日历升高，而不是让整条公式跟着 \\(T-t\\) 跑。</p><p><span class="marginnote">「不依赖时间」是近似的产品，不是市场定律。隔夜跳空、拍卖、宏观发布仍应把惩罚或 \\(\\sigma\\) 写成日历函数。GLFT 去掉的是 AS 里那个线性的剩余时间因子，不是所有非平稳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>HJB 对价值函数 \\(\\theta(q)\\)（分离中间价与现金之后）给出差分—微分方程：扩散贡献库存风险，买卖强度贡献对 \\(\\delta\\) 的一阶条件。指数强度下，最优距离有</p> \\[\\delta^{a\\star}(q)=\\frac{1}{\\kappa}+\\frac{1}{\\gamma}\\ln\\Bigl(1+\\frac{\\gamma}{\\kappa}\\Bigr)-\\bigl(\\theta(q)-\\theta(q-1)\\bigr) \\]<p>一类形式（买侧对称，符号随库存增量翻转）。\\(\\theta(q)-\\theta(q-1)\\) 是再买（或再卖）一单位库存的无差异价格调整，即偏度。对小 \\(q\\)、二次惩罚，\\(\\theta\\) 近似二次，偏度对 \\(q\\) 近似线性，宽度对 \\(q\\) 近似常数——这就是实务里「线性 inventory skew + 波动目标价差」的理论原型。</p><p><strong>库存限额。</strong> 在 \\(\\pm Q\\) 处，越界的那一侧 \\(\\lambda\\) 被设为零，HJB 变成边界条件。靠近限额时 \\(\\theta\\) 的差分变陡，偏度非线性放大，直到一侧撤出。这比把 \\(\\gamma\\) 调大更符合风控：限额是合规对象，\\(\\gamma\\) 是偏好。多资产版本里 \\(q\\) 是向量，惩罚用协方差矩阵，\\(\\theta\\) 的差分给出交叉偏度——持有正相关的另一腿时，本腿也要 skew，即使本腿库存为零。</p><h3 id="从-as-到-glft-的参数迁移" tabindex="-1">从 AS 到 GLFT 的参数迁移 <a class="header-anchor" href="#从-as-到-glft-的参数迁移" aria-label="Permalink to &quot;从 AS 到 GLFT 的参数迁移&quot;">​</a></h3><p>AS 的 \\(\\gamma\\sigma^2(T-t)\\) 在 \\(t\\) 靠近 \\(T\\) 时发散式变大，尾盘报价会宽到不再成交。GLFT 用固定惩罚代替，尾盘行为改由你是否显式升高惩罚或降低 \\(Q\\) 来决定，成为可审计的日历规则。校准仍难：\\(A,\\kappa\\) 不是从一档深度读出的物理常数，而是填成对距离的弹性。应用自己的限价成交与取消数据估 \\(\\kappa\\)，用库存方差与风险预算定惩罚，而不是从论文表格抄四个数字。费率应进入每笔跳的现金增量，见 <a href="/quant/maker-taker">maker-taker</a>。</p><p><span class="marginnote">闭式近似依赖指数强度与指数效用。幂效用、线性强度、或填成依赖队列长度时，应回到数值 HJB 或把 GLFT 当初值。生产系统里「GLFT」多半指线性偏度加强度价差这一结构，不是原文 ODE 的逐日重估。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>报价仍是二维控制：宽度卖库存方差与被选中强度，偏度卖把 \\(q\\) 拉回零（或拉离限额）。成交后 \\(q\\) 跳一档，\\(\\theta\\) 的差分立刻变，原先远的一侧变近。没有新闻也要改价，这是存货驱动的修订。与 AS 相同，流是外生泊松，解释不了成交后价格朝成交方向跳的毒性；那要叠加短期 alpha 或逆向选择，见 <a href="/quant/cartea-jaimungal">Cartea–Jaimungal</a> 与 <a href="/quant/toxic-flow">毒性流</a>。</p><p>限额改变漂移。靠近 \\(Q\\) 时买入强度被压制，库存过程变成有边界的受控跳过程，期望持有时间下降，价差收入也下降——做市在限额附近退化成单向减仓。最优 \\(Q\\) 是风险资本：太窄则整天停在边界上赚不到双边价差；太宽则 \\(\\theta\\) 的曲率不够，库存像随机游走。这与 <a href="/quant/inventory-skew">库存偏度</a> 的工程表述一致，GLFT 提供的是 \\(\\theta\\) 的来源。</p><h3 id="多资产与对冲腿" tabindex="-1">多资产与对冲腿 <a class="header-anchor" href="#多资产与对冲腿" aria-label="Permalink to &quot;多资产与对冲腿&quot;">​</a></h3><p>协方差进入惩罚后，做市标的与对冲期货的库存应在同一 \\(\\theta\\) 里。现货多头加期货空头可以降低惩罚，偏度相对净风险而不是相对现货股数。漏记对冲腿会把已经中性的簿再 skew 一遍。交叉到达（买 A 的流与卖 B 的流相关）会再改强度；原文的基准设定往往是独立泊松，实务要按品种对估计，否则多资产闭式只是把 AS 的错误乘上矩阵。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>算术中间价、单位成交、无成本改价、无队列，与 AS 同一组理想化。FIFO 上每次改价丧失时间优先，连续距离控制高估了可重置性。涨跌停与拍卖要把强度模型换成机制特定的填成。隔夜库存的惩罚应大于日内，否则模型鼓励把风险堆到收盘后。</p><p>不要把 GLFT 的线性偏度当成对毒性的防御：知情流专门在你库存错误的一侧成交，线性 skew 可能加码亏损。也不要在多品种上共用一个 \\(\\kappa\\)。校准应走滚动、点-in-time 的填成估计，禁止用全样本事后强度。公式不包含共同定位或撮合优先级；那些不是本模型的对象。</p><p><span class="marginnote">论文解决的是存货约束下的做市 HJB，标题里的 inventory risk 不是市场风险部的 VaR 限额说明书。把 \\(Q\\) 直接写成合规限额可以，但 \\(\\gamma\\) 与惩罚系数仍须与该限额一致，否则 HJB 的内点解会先于限额被风控砍掉。</span></p>',26)),(e(),s(d,null,{default:n(()=>[p(l,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%B8%AD%E9%97%B4%E4%BB%B7%20S%22%5D%20--%3E%20TH%5B%22%E4%BB%B7%E5%80%BC%20%CE%B8(q)%EF%BC%9A%E7%BB%88%E7%AB%AF%E5%BA%93%E5%AD%98%E6%83%A9%E7%BD%9A%22%5D%0A%20%20Q%5B%22%E5%BA%93%E5%AD%98%20q%20%E4%B8%8E%E9%99%90%E9%A2%9D%20%C2%B1Q%22%5D%20--%3E%20TH%0A%20%20TH%20--%3E%20SK%5B%22%E5%81%8F%E5%BA%A6%EF%BC%9A%CE%B8(q)-%CE%B8(q%C2%B11)%22%5D%0A%20%20INT%5B%22%E5%BC%BA%E5%BA%A6%20%CE%BB%20%3D%20A%20e%5E%7B-%CE%BA%CE%B4%7D%22%5D%20--%3E%20W%5B%22%E5%AE%BD%E5%BA%A6%EF%BC%9A1%2F%CE%BA%20%2B%20%CE%B3%5E%7B-1%7D%20ln(1%2B%CE%B3%2F%CE%BA)%22%5D%0A%20%20SK%20--%3E%20DIST%5B%22%E6%9C%80%E4%BC%98%E8%B7%9D%E7%A6%BB%20%CE%B4%E1%B5%83(q)%2C%20%CE%B4%E1%B5%87(q)%22%5D%0A%20%20W%20--%3E%20DIST%0A%20%20DIST%20--%3E%20FILL%5B%22%E6%B3%8A%E6%9D%BE%E6%88%90%E4%BA%A4%22%5D%0A%20%20FILL%20--%3E%20Q%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GLFT（2013）在指数效用与指数强度下，用终端库存惩罚得到可计算的做市距离，偏度来自 \\(\\theta(q)\\) 的差分。</li><li>相对 Avellaneda–Stoikov，宽度与偏度不必显式乘上剩余时间；尾盘行为改由惩罚与限额的日历规则承担。</li><li>库存硬约束在边界关闭一侧强度，靠近限额时偏度非线性变陡。</li><li>多资产惩罚应用净风险与协方差，而不是单腿股数。</li><li>仍无毒性、无队列成本；生产「GLFT」多半借用线性 skew 结构，而非逐日 ODE。</li><li>出处：Guéant, Lehalle and Fernandez-Tapia, <em>Mathematics and Financial Economics</em>, 2013；Avellaneda and Stoikov, <em>Quantitative Finance</em>, 2008；Ho and Stoll, <em>Journal of Financial Economics</em>, 1981。</li></ul>',2))])}const k=i(h,[["render",B]]);export{q as __pageData,k as default};
